package automations

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// nextRunFixtures is testdata/nextrun.json, generated by testdata/gen.ts from
// the real TypeScript implementation (packages/services/src/session/
// automationCron.ts, croner). Never edit it by hand:
//
//	PATH=/Users/tylinux/.nvm/versions/node/v24.21.0/bin:$PATH \
//	  node_modules/.bin/tsx next/server/internal/automations/testdata/gen.ts
type nextRunFixtures struct {
	Cron []struct {
		Timezone  string `json:"timezone"`
		From      string `json:"from"`
		CronExpr  string `json:"cronExpr"`
		NextRunAt *int64 `json:"nextRunAt"`
	} `json:"cron"`
	ScheduleRule []struct {
		Timezone          string       `json:"timezone"`
		From              string       `json:"from"`
		Rule              ScheduleRule `json:"rule"`
		NextRunAt         *int64       `json:"nextRunAt"`
		AutomationNextRun *int64       `json:"automationNextRunAt"`
	} `json:"scheduleRule"`
	Previous []struct {
		Timezone      string `json:"timezone"`
		From          string `json:"from"`
		CronExpr      string `json:"cronExpr"`
		PreviousRunAt *int64 `json:"previousRunAt"`
	} `json:"previous"`
}

func loadFixtures(t *testing.T) nextRunFixtures {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "nextrun.json"))
	if err != nil {
		t.Fatalf("reading fixtures: %v", err)
	}
	var fixtures nextRunFixtures
	if err := json.Unmarshal(raw, &fixtures); err != nil {
		t.Fatalf("decoding fixtures: %v", err)
	}
	return fixtures
}

func mustLocation(t *testing.T, name string) *time.Location {
	t.Helper()
	loc, err := time.LoadLocation(name)
	if err != nil {
		t.Fatalf("loading %s: %v", name, err)
	}
	return loc
}

func millisOrZero(value *int64) int64 {
	if value == nil {
		return 0
	}
	return *value
}

func formatInstant(ms int64, loc *time.Location) string {
	return time.UnixMilli(ms).In(loc).Format(time.RFC3339)
}

// TestCronNextParity proves cron math matches computeNextRunAt (croner) for
// every fixture case, including DST transitions.
func TestCronNextParity(t *testing.T) {
	fixtures := loadFixtures(t)
	if len(fixtures.Cron) == 0 {
		t.Fatal("no cron fixtures")
	}
	for caseIndex, fixture := range fixtures.Cron {
		t.Run(fmt.Sprintf("cron/%03d", caseIndex), func(t *testing.T) {
			loc := mustLocation(t, fixture.Timezone)
			from := time.UnixMilli(mustParseInstant(t, fixture.From)).In(loc)
			expr, err := parseCronExpr(fixture.CronExpr)
			if err != nil {
				t.Fatalf("parseCronExpr(%q): %v", fixture.CronExpr, err)
			}
			next, ok := expr.next(from, loc)
			switch {
			case fixture.NextRunAt == nil && ok:
				t.Fatalf("want no next run, got %s", formatInstant(next.UnixMilli(), loc))
			case fixture.NextRunAt != nil && !ok:
				t.Fatalf("want %s, got none", formatInstant(*fixture.NextRunAt, loc))
			case fixture.NextRunAt != nil && next.UnixMilli() != *fixture.NextRunAt:
				t.Fatalf("want %s, got %s", formatInstant(*fixture.NextRunAt, loc), formatInstant(next.UnixMilli(), loc))
			}
			if !ok {
				return
			}
			// The result must be the next occurrence on the wall clock too.
			again, okAgain := expr.next(next, loc)
			if okAgain && !again.After(next) {
				t.Fatalf("next after %s is not increasing: %s", formatInstant(next.UnixMilli(), loc), formatInstant(again.UnixMilli(), loc))
			}
		})
	}
}

// TestCronPreviousParity proves previousRunAt (used by the stale one-shot
// window) matches croner's previousRuns.
func TestCronPreviousParity(t *testing.T) {
	fixtures := loadFixtures(t)
	if len(fixtures.Previous) == 0 {
		t.Fatal("no previous fixtures")
	}
	for caseIndex, fixture := range fixtures.Previous {
		t.Run(fmt.Sprintf("previous/%03d", caseIndex), func(t *testing.T) {
			loc := mustLocation(t, fixture.Timezone)
			from := time.UnixMilli(mustParseInstant(t, fixture.From)).In(loc)
			expr, err := parseCronExpr(fixture.CronExpr)
			if err != nil {
				t.Fatalf("parseCronExpr(%q): %v", fixture.CronExpr, err)
			}
			previous, ok := expr.previous(from, loc)
			if fixture.PreviousRunAt == nil {
				if ok {
					t.Fatalf("want none, got %s", formatInstant(previous.UnixMilli(), loc))
				}
				return
			}
			if !ok {
				t.Fatalf("want %s, got none", formatInstant(*fixture.PreviousRunAt, loc))
			}
			if previous.UnixMilli() != *fixture.PreviousRunAt {
				t.Fatalf("want %s, got %s", formatInstant(*fixture.PreviousRunAt, loc), formatInstant(previous.UnixMilli(), loc))
			}
		})
	}
}

// TestScheduleRuleParity proves every scheduleRule unit matches
// computeScheduleRuleNextRunAt evaluated in the automation's zone.
func TestScheduleRuleParity(t *testing.T) {
	fixtures := loadFixtures(t)
	if len(fixtures.ScheduleRule) == 0 {
		t.Fatal("no scheduleRule fixtures")
	}
	for caseIndex, fixture := range fixtures.ScheduleRule {
		rule := fixture.Rule
		t.Run(fmt.Sprintf("rule/%03d", caseIndex), func(t *testing.T) {
			loc := mustLocation(t, fixture.Timezone)
			from := time.UnixMilli(mustParseInstant(t, fixture.From)).In(loc)
			next, ok := scheduleNext(&rule, from, loc)
			if os.Getenv("PARITY_TRACE") != "" {
				t.Logf("trace interval=%v hour=%v minute=%v weekdays=%v anchor=%v from=%d next=%d", rule.Interval, rule.Hour, rule.Minute, rule.Weekdays, rule.AnchorAt, from.UnixMilli(), next.UnixMilli())
			}
			if fixture.NextRunAt == nil {
				if ok {
					t.Fatalf("want none, got %s", formatInstant(next.UnixMilli(), loc))
				}
				return
			}
			if !ok {
				t.Fatalf("want %s, got none", formatInstant(*fixture.NextRunAt, loc))
			}
			if next.UnixMilli() != *fixture.NextRunAt {
				t.Fatalf("want %s, got %s", formatInstant(*fixture.NextRunAt, loc), formatInstant(next.UnixMilli(), loc))
			}
			automation := Automation{CronExpr: "* * * * *", ScheduleRule: &rule}
			combined, okCombined := nextRunAt(&automation, from, loc)
			if !okCombined || combined.UnixMilli() != millisOrZero(fixture.AutomationNextRun) {
				t.Fatalf("nextRunAt disagrees with instrumentation: want %d, got %s", millisOrZero(fixture.AutomationNextRun), formatInstant(combined.UnixMilli(), loc))
			}
		})
	}
}

func mustParseInstant(t *testing.T, value string) int64 {
	t.Helper()
	parsed, err := time.Parse(time.RFC3339Nano, value)
	if err != nil {
		t.Fatalf("parsing %q: %v", value, err)
	}
	return parsed.UnixMilli()
}

// TestV8DateSemantics pins the two `new Date(fields)` rules that Go's
// time.Date does not share; both were checked against Node 24 (V8) directly.
func TestV8DateSemantics(t *testing.T) {
	newYork := mustLocation(t, "America/New_York")
	berlin := mustLocation(t, "Europe/Berlin")
	cases := []struct {
		name string
		loc  *time.Location
		wall wall
		want string // RFC3339 in UTC
	}{
		// Spring forward: 02:00 → 03:00. V8 moves the wall fields FORWARD by
		// the gap; time.Date would return the transition instant (07:00Z).
		{"gap 02:30", newYork, wallFields(2026, 3, 8, 2, 30), "2026-03-08T07:30:00Z"},
		{"gap 02:00", newYork, wallFields(2026, 3, 8, 2, 0), "2026-03-08T07:00:00Z"},
		{"gap 02:59", berlin, wallFields(2026, 3, 29, 2, 59), "2026-03-29T01:59:00Z"},
		// Fall back: 02:00 → 01:00. V8 picks the EARLIER offset (EDT/CEST);
		// time.Date picks the later one (06:30Z / 01:30Z).
		{"overlap 01:30", newYork, wallFields(2026, 11, 1, 1, 30), "2026-11-01T05:30:00Z"},
		{"overlap 02:30 CET", berlin, wallFields(2026, 10, 25, 2, 30), "2026-10-25T00:30:00Z"},
		// Ordinary readings agree with time.Date.
		{"ordinary", newYork, wallFields(2026, 3, 8, 10, 0), "2026-03-08T14:00:00Z"},
	}
	for _, fixture := range cases {
		t.Run(fixture.name, func(t *testing.T) {
			got := instantOf(fixture.wall, fixture.loc, dateV8).UTC().Format(time.RFC3339)
			if got != fixture.want {
				t.Fatalf("dateV8: want %s, got %s", fixture.want, got)
			}
		})
	}
	// The Go-style reading differs exactly where V8 does; this guards that the
	// distinction is still real (it documents the bug being emulated).
	goGap := instantOf(wallFields(2026, 3, 8, 2, 30), newYork, dateGoStyle).UTC()
	if want := "2026-03-08T07:00:00Z"; goGap.Format(time.RFC3339) != want {
		t.Fatalf("dateGoStyle gap: want %s, got %s", want, goGap.Format(time.RFC3339))
	}
}

// TestCronDSTBehaviour pins croner's transition behaviour (probed against
// croner 10.0.1 under TZ=America/New_York / Europe/Berlin).
func TestCronDSTBehaviour(t *testing.T) {
	newYork := mustLocation(t, "America/New_York")
	berlin := mustLocation(t, "Europe/Berlin")
	cases := []struct {
		name string
		loc  *time.Location
		expr string
		from string
		want string
	}{
		// Spring forward: a gap hour fires once, shifted by the gap.
		{"gap 02:00", newYork, "0 2 * * *", "2026-03-08T01:30:00Z", "2026-03-08T07:00:00Z"},
		{"gap 02:30", newYork, "30 2 * * *", "2026-03-08T01:30:00Z", "2026-03-08T07:30:00Z"},
		{"gap 02:30 after", newYork, "30 2 * * *", "2026-03-08T06:30:00Z", "2026-03-08T07:30:00Z"},
		{"gap 02:00 Berlin", berlin, "0 2 * * *", "2026-03-29T00:30:00Z", "2026-03-29T01:00:00Z"},
		// The landing hour is produced normally afterwards.
		{"landing 03:00", newYork, "0 3 * * *", "2026-03-08T01:30:00Z", "2026-03-08T07:00:00Z"},
		// Fall back: an ambiguous minute fires once, at its earlier instant.
		{"overlap every minute", newYork, "* * * * *", "2026-11-01T05:30:00Z", "2026-11-01T05:31:00Z"},
		{"overlap */5", newYork, "*/5 * * * *", "2026-11-01T04:50:00Z", "2026-11-01T04:55:00Z"},
		{"overlap 30 *", newYork, "30 * * * *", "2026-11-01T05:30:00Z", "2026-11-01T07:30:00Z"},
		// From inside the SECOND pass croner rewinds into the first pass.
		{"second pass rewind", newYork, "* * * * *", "2026-11-01T06:30:00Z", "2026-11-01T05:31:00Z"},
		{"second pass rewind */5", newYork, "*/5 * * * *", "2026-11-01T06:30:00Z", "2026-11-01T05:35:00Z"},
		{"second pass Berlin hourly", berlin, "0 * * * *", "2026-10-25T00:30:00Z", "2026-10-25T02:00:00Z"},
	}
	for _, fixture := range cases {
		t.Run(fixture.name, func(t *testing.T) {
			expr, err := parseCronExpr(fixture.expr)
			if err != nil {
				t.Fatalf("parseCronExpr: %v", err)
			}
			from := time.UnixMilli(mustParseInstant(t, fixture.from)).In(fixture.loc)
			next, ok := expr.next(from, fixture.loc)
			if !ok {
				t.Fatalf("want %s, got none", fixture.want)
			}
			if got := next.UTC().Format(time.RFC3339); got != fixture.want {
				t.Fatalf("want %s, got %s", fixture.want, got)
			}
		})
	}
}
